def valid_date(date):
    if not date:
        return False

    month, day, year = map(int, date.split('-'))

    if month < 1 or month > 12:
        return False

    if month == 1:
        if day < 1 or day > 29:
            return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [2, 4, 6, 8, 9, 11]:
        if day < 1 or day > 30:
            return False

    return True
